use serde_json::Value;

pub fn solve(input: Value) -> Value {
    if let Value::Array(arr) = input {
        if arr.len() <= 1 {
            return Value::Array(vec![]);
        }
        let mut result = Vec::with_capacity(arr.len() - 1);
        for window in arr.windows(2) {
            if let (Value::Number(n1), Value::Number(n2)) = (window[0], window[1]) {
                if let (Some(n1), Some(n2)) = (n1.as_i64(), n2.as_i64()) {
                    result.push((n2 - n1).into());
                }
            }
        }
        Value::Array(result)
    } else {
        Value::Array(vec![])
    }
}
